import{_ as e,c as o,o as t,aj as a}from"./chunks/framework.B-K7myP5.js";const u=JSON.parse('{"title":"如何为我的框架自定义一个扩展包安装目录？","frontmatter":{"title":"如何为我的框架自定义一个扩展包安装目录？","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/do-i-install-a-package-to-a-custom-path-for-my-framework.html","lastUpdated":"2026-01-22","tags":[],"link":"/docs/composer/index","layout":"doc","sidebar":true,"aside":true,"next":{"text":"如何使用脚本安装 Composer？","link":"/docs/composer/常见问题/to-install-composer-programmatically"}},"headers":[],"params":{"pkg":"composer/index","sidebar":[{"text":"常见问题","items":[{"text":"如何为我的框架自定义一个扩展包安装目录？","link":"/docs/composer/index"},{"text":"如何使用脚本安装 Composer？","link":"/docs/composer/常见问题/to-install-composer-programmatically"},{"text":"使用 root 用户来安装扩展包是否安全？如何安全地安装未认证渠道的扩展包？","link":"/docs/composer/常见问题/to-install-untrusted-packages-safely"},{"text":"我应该将 vendor 目录加入版本控制吗？","link":"/docs/composer/常见问题/i-commit-the-dependencies-in-my-vendor-directory"},{"text":"Composer 使用的是什么版本命名规范？","link":"/docs/composer/常见问题/version-numbering-system-does-composer-itself-use"},{"text":"为什么限制版本是最佳实践？","link":"/docs/composer/常见问题/are-unbound-version-constraints-a-bad-idea"},{"text":"为何版本限制与对比符、通配符配合使用是个糟糕的行为？","link":"/docs/composer/常见问题/are-version-constraints-combining-comparisons-and-wildcards-a-bad-idea"},{"text":"为什么 Composer 不递归加载代码库？","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively"}]},{"text":"官方文章","items":[{"text":"分支别名","link":"/docs/composer/官方文章/aliases"},{"text":"版本限制","link":"/docs/composer/官方文章/versions"},{"text":"自动加载器优化","link":"/docs/composer/官方文章/optimization"},{"text":"自定义安装器","link":"/docs/composer/官方文章/installers"},{"text":"使用 Satis 处理私有仓库","link":"/docs/composer/官方文章/private-packages-with-satis"},{"text":"HTTP 基础认证","link":"/docs/composer/官方文章/basic-authentication"},{"text":"创建 Composer 插件","link":"/docs/composer/官方文章/plugins"},{"text":"事件和自定义脚本","link":"/docs/composer/官方文章/scripts"},{"text":"故障排除","link":"/docs/composer/官方文章/troubleshooting"},{"text":"可执行二进制文件","link":"/docs/composer/官方文章/binaries"}]},{"text":"教程","items":[{"text":"简介","link":"/docs/composer/教程/intro"},{"text":"基本使用","link":"/docs/composer/教程/basic-usage"},{"text":"创建扩展包","link":"/docs/composer/教程/libraries"},{"text":"Composer 命令的使用","link":"/docs/composer/教程/cli"},{"text":"json 完全解析","link":"/docs/composer/教程/schema"},{"text":"扩展包源仓库","link":"/docs/composer/教程/repositories"},{"text":"配置信息","link":"/docs/composer/教程/config"},{"text":"社区","link":"/docs/composer/教程/community"}]}],"versions":[]},"relativePath":"docs/composer/index.md","filePath":"docs/[pkg].md"}'),n={name:"docs/composer/index.md"};function i(p,s,r,c,l,d){return t(),o("div",null,[...s[0]||(s[0]=[a(`<h1 id="如何为我的框架自定义一个扩展包安装目录" tabindex="-1">如何为我的框架自定义一个扩展包安装目录？ <a class="header-anchor" href="#如何为我的框架自定义一个扩展包安装目录" aria-label="Permalink to “如何为我的框架自定义一个扩展包安装目录？”">​</a></h1><p>每个框架都有一个或多个不同的拓展包安装目录。Composer 可以通过使用 <a href="https://github.com/composer/installers" target="_blank" rel="noreferrer">composer/installers</a> 来配置拓展包到其它的目录，而不是默认的<code>vendor</code>目录。</p><p>如果你是一个包作者并且希望你的包被安装到自定义的目录中，只需要安装 <code>composer/installers</code>依赖，并设置适当的<code>type</code>属性。 这是常见的方式，如果你的包专门用于一个特定的框架，如 CakePHP、Drupal 或 WordPress。下面是一个 WordPress 主题的 composer.json 文件实例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;name&quot;: &quot;you/themename&quot;,</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;wordpress-theme&quot;,</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;composer/installers&quot;: &quot;~1.0&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在当你用 Composer 安装这个主题时，它就会被放置在 <code>wp-content/themes/themename/</code>目录中。 <a href="https://github.com/composer/installers#current-supported-package-types" target="_blank" rel="noreferrer">查看当前支持的 type 类型</a>。 作为一个包使用者你可以设置或覆盖拓展包的安装路径，需要依赖<code>composer/installers</code>并在 extra 下设置 installer-paths 属性。Drupal 的多站点设置就是一个很好的例子，其中的资源包应该被安装到各自网站的子目录。下面我们使用<code>composer/installers</code>来覆盖安装路径：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;extra&quot;: {</span></span>
<span class="line"><span>        &quot;installer-paths&quot;: {</span></span>
<span class="line"><span>            &quot;sites/example.com/modules/{$name}&quot;: [&quot;vendor/package&quot;]</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在该拓展包将被安装到你指定的目录，而不是<code>composer/installers</code>默认指定目录。</p><blockquote><p>注意：你不能使用这种方式来修改任意包的安装目录。这种方式只适用于依赖<code>composer/installers</code>并使用自定义 type 控制的拓展包。</p></blockquote>`,8)])])}const k=e(n,[["render",i]]);export{u as __pageData,k as default};
